P(s, pc) {
  let t = String(s == null ? '' : s).trim().replace(/^R\$\s*/i, '').replace(/\s*%$/, '').replace(/\s+/g, '');
  if (!t) return { st: 'empty' };
  if (/^[-−–]/.test(t)) return { st: 'bad', msg: 'O valor não pode ser negativo.' };
  if (t.indexOf(',') >= 0) t = t.replace(/\./g, '').replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(t)) t = t.replace(/\./g, '');
  if (!/^\d+(\.\d+)?$/.test(t)) return { st: 'bad', msg: 'Use apenas números, por exemplo 25.000,00.' };
  const v = Number(t);
  if (!Number.isFinite(v)) return { st: 'bad', msg: 'Valor grande demais para calcular.' };
  if (pc && v > 100) return { st: 'bad', msg: 'Informe um percentual de 0 a 100.' };
  return { st: 'ok', v };
}

